import { PASSWORD, USERS, expect, test } from "../../fixtures";

test.describe("AUTH-03 sign in with unknown email", () => {
  test("unknown email is rejected with 401 invalid_credentials", { tag: "@AUTH-03" }, async ({ request }) => {
    // Act
    const response = await request.post("/api/auth/login", {
      data: { email: "nobody@northwind.test", password: PASSWORD },
    });

    // Assert
    expect(response.status()).toBe(401);
    const body = await response.json();
    expect(body.error.code).toBe("invalid_credentials");
  });

  test("unknown email is rejected the same way as a wrong password", { tag: "@AUTH-03" }, async ({ request }) => {
    // Arrange
    const wrongPassword = await request.post("/api/auth/login", {
      data: { email: USERS.member, password: "wrong-password" },
    });

    // Act
    const unknownEmail = await request.post("/api/auth/login", {
      data: { email: "nobody@northwind.test", password: PASSWORD },
    });

    // Assert
    expect(unknownEmail.status()).toBe(wrongPassword.status());
    expect(unknownEmail.status()).toBe(401);
    const unknownBody = await unknownEmail.json();
    const wrongBody = await wrongPassword.json();
    expect(unknownBody.error.code).toBe("invalid_credentials");
    expect(unknownBody.error.code).toBe(wrongBody.error.code);
  });
});
